#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "ScoreTracker is a raw C++ pointer without the UPROPERTY() macro in ArenaGameMode.h (unlike Hud and Palette, which are UPROPERTY TObjectPtr). The Unreal garbage collector therefore does not see it as a reference and collects the UArenaScoreTracker created in BeginPlay; the log shows a GC pass purging 412 objects at 21.05.13, 14 seconds before the crash. When the next goal is scored, AArenaGameMode::OnGoalScored dereferences the now-dangling ScoreTracker pointer inside UArenaScoreTracker::AddPoints(), causing EXCEPTION_ACCESS_VIOLATION. Fixed by making ScoreTracker a UPROPERTY() TObjectPtr<UArenaScoreTracker> so the GC keeps it alive.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary is loaded at runtime with LoadObject using a string path, so the cooker cannot detect it as a reference. With bCookAll=False and DirectoriesToAlwaysCook listing only /Game/Data/Effects, the /Game/Data/Palettes directory is never cooked into the pak. In the packaged build LoadObject fails (log: 'Couldn't find file for package /Game/Data/Palettes/DA_Primary'), the palette is null, and the game falls back to gray. Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook in Config/DefaultGame.ini."
}
